        let variant: Int32 = try readInt(&buf)
        switch variant {
        
        case 1: return .setCategory(categoryId: try FfiConverterString.read(from: &buf)
        )
        
        case 2: return .addTag(tag: try FfiConverterString.read(from: &buf)
        )
        
        case 3: return .renameMerchant(to: try FfiConverterString.read(from: &buf)
        )
        
        case 4: return .flag(reason: try FfiConverterString.read(from: &buf)
        )
        
        case 5: return .ignore
        
        default: throw UniffiInternalError.unexpectedEnumCase
        }
