        let variant: Int32 = try readInt(&buf)
        switch variant {
        
        case 1: return .merchant(try FfiConverterTypeMerchantMatch.read(from: &buf)
        )
        
        case 2: return .amountRange(minMinor: try FfiConverterOptionInt64.read(from: &buf), maxMinor: try FfiConverterOptionInt64.read(from: &buf)
        )
        
        case 3: return .currency(code: try FfiConverterString.read(from: &buf)
        )
        
        case 4: return .dayOfMonthMax(n: try FfiConverterUInt32.read(from: &buf)
        )
        
        case 5: return .direction(value: try FfiConverterString.read(from: &buf)
        )
        
        case 6: return .account(value: try FfiConverterString.read(from: &buf)
        )
        
        case 7: return .source(value: try FfiConverterString.read(from: &buf)
        )
        
        default: throw UniffiInternalError.unexpectedEnumCase
        }
