public 
enum CoreError: Swift.Error, Equatable, Hashable, Foundation.LocalizedError {

    
    
    case UnknownCurrency(String
    )
    case MismatchedCurrencies(a: String, b: String
    )
    case Overflow
    /**
     * Malformed boundary input: bad hex, wrong lengths, empty strings.
     */
    case InvalidInput(String
    )
    case EmptyParticipants
    case DuplicateParticipant
    case UnknownParticipant
    case NonPositiveWeight
    case NegativeTotal
    case PercentMismatch(gotBps: UInt64
    )
    case ExactSumMismatch(expected: Int64, got: Int64
    )
    case DeltasExceedTotal
    case LineAmountNonPositive
    case EmptyLineAssignment
    case TotalMismatch(expected: Int64, got: Int64
    )

    

    

    
    public var errorDescription: String? {
        String(reflecting: self)
    }
    
}

#if compiler(>=6)
extension CoreError: Sendable {}
#endif

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeCoreError: FfiConverterRustBuffer {
    typealias SwiftType = CoreError

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> CoreError {
        let variant: Int32 = try readInt(&buf)
        switch variant {

        

        
        case 1: return .UnknownCurrency(
            try FfiConverterString.read(from: &buf)
            )
        case 2: return .MismatchedCurrencies(
            a: try FfiConverterString.read(from: &buf), 
            b: try FfiConverterString.read(from: &buf)
            )
        case 3: return .Overflow
        case 4: return .InvalidInput(
            try FfiConverterString.read(from: &buf)
            )
        case 5: return .EmptyParticipants
        case 6: return .DuplicateParticipant
        case 7: return .UnknownParticipant
        case 8: return .NonPositiveWeight
        case 9: return .NegativeTotal
        case 10: return .PercentMismatch(
            gotBps: try FfiConverterUInt64.read(from: &buf)
            )
        case 11: return .ExactSumMismatch(
            expected: try FfiConverterInt64.read(from: &buf), 
            got: try FfiConverterInt64.read(from: &buf)
            )
        case 12: return .DeltasExceedTotal
        case 13: return .LineAmountNonPositive
        case 14: return .EmptyLineAssignment
        case 15: return .TotalMismatch(
            expected: try FfiConverterInt64.read(from: &buf), 
            got: try FfiConverterInt64.read(from: &buf)
            )

         default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: CoreError, into buf: inout [UInt8]) {
        switch value {

        

        
        
        case let .UnknownCurrency(v1):
            writeInt(&buf, Int32(1))
            FfiConverterString.write(v1, into: &buf)
            
        
        case let .MismatchedCurrencies(a,b):
            writeInt(&buf, Int32(2))
            FfiConverterString.write(a, into: &buf)
            FfiConverterString.write(b, into: &buf)
            
        
        case .Overflow:
            writeInt(&buf, Int32(3))
        
        
        case let .InvalidInput(v1):
            writeInt(&buf, Int32(4))
            FfiConverterString.write(v1, into: &buf)
            
        
        case .EmptyParticipants:
            writeInt(&buf, Int32(5))
        
        
        case .DuplicateParticipant:
            writeInt(&buf, Int32(6))
        
        
        case .UnknownParticipant:
            writeInt(&buf, Int32(7))
        
        
        case .NonPositiveWeight:
            writeInt(&buf, Int32(8))
        
        
        case .NegativeTotal:
            writeInt(&buf, Int32(9))
        
        
        case let .PercentMismatch(gotBps):
            writeInt(&buf, Int32(10))
            FfiConverterUInt64.write(gotBps, into: &buf)
            
        
        case let .ExactSumMismatch(expected,got):
            writeInt(&buf, Int32(11))
            FfiConverterInt64.write(expected, into: &buf)
            FfiConverterInt64.write(got, into: &buf)
            
        
        case .DeltasExceedTotal:
            writeInt(&buf, Int32(12))
        
        
        case .LineAmountNonPositive:
            writeInt(&buf, Int32(13))
        
        
        case .EmptyLineAssignment:
            writeInt(&buf, Int32(14))
        
        
        case let .TotalMismatch(expected,got):
            writeInt(&buf, Int32(15))
            FfiConverterInt64.write(expected, into: &buf)
            FfiConverterInt64.write(got, into: &buf)
            
        }
    }
}


