     * Valid JSON, but not a SKIPTI ledger export.
     */
    case WrongFormatTag(String
    )
    /**
     * A SKIPTI export, but written by a different schema generation.
     */
    case UnsupportedSchemaVersion(found: UInt64, supported: UInt64
    )
    /**
