    static let vtable: UniffiVTableCallbackInterfaceSkiptiKeystore = UniffiVTableCallbackInterfaceSkiptiKeystore(
        uniffiFree: { (uniffiHandle: UInt64) -> () in
            do {
                try FfiConverterCallbackInterfaceSkiptiKeystore.handleMap.remove(handle: uniffiHandle)
            } catch {
                print("Uniffi callback interface SkiptiKeystore: handle missing in uniffiFree")
            }
        },
        uniffiClone: { (uniffiHandle: UInt64) -> UInt64 in
            do {
                return try FfiConverterCallbackInterfaceSkiptiKeystore.handleMap.clone(handle: uniffiHandle)
            } catch {
